import{_ as l,o as i,c as e,O as r}from"./chunks/framework.db831a78.js";const b=JSON.parse('{"title":"分布式 & 高并发","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/08-分布式高并发.md","filePath":"interview/后端/Java/08-分布式高并发.md","lastUpdated":null}'),t={name:"interview/后端/Java/08-分布式高并发.md"};function h(o,a,n,d,u,s){return i(),e("div",null,a[0]||(a[0]=[r('<h1 id="分布式-高并发" tabindex="-1">分布式 &amp; 高并发 <a class="header-anchor" href="#分布式-高并发" aria-label="Permalink to &quot;分布式 &amp; 高并发&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="cap-定理与-base-理论-★★★" tabindex="-1">CAP 定理与 BASE 理论 ★★★ <a class="header-anchor" href="#cap-定理与-base-理论-★★★" aria-label="Permalink to &quot;CAP 定理与 BASE 理论 ★★★&quot;">​</a></h2><h3 id="cap" tabindex="-1">CAP <a class="header-anchor" href="#cap" aria-label="Permalink to &quot;CAP&quot;">​</a></h3><ul><li>Consistency（一致性）：所有节点同一时间数据一致。</li><li>Availability（可用性）：每个请求都能得到响应（不保证最新）。</li><li>Partition tolerance（分区容错性）：网络分区时系统仍能工作。</li><li>结论：分布式系统必须保证 P（网络分区不可避免），所以只能在 C 和 A 之间取舍，无法三者兼得。</li></ul><h3 id="base" tabindex="-1">BASE <a class="header-anchor" href="#base" aria-label="Permalink to &quot;BASE&quot;">​</a></h3><ul><li>Basically Available（基本可用）、Soft state（软状态）、Eventually consistent（最终一致）。</li><li>对 CAP 的权衡：不追求强一致，接受最终一致，保证基本可用。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「CP 和 AP 例子？」→ CP 牺牲可用性保证一致（如 ZooKeeper、etcd、Nacos CP 模式）；AP 牺牲强一致保证可用（如 Eureka、Nacos AP 模式）。</li></ul><hr><h2 id="分布式事务解决方案-★★★" tabindex="-1">分布式事务解决方案 ★★★ <a class="header-anchor" href="#分布式事务解决方案-★★★" aria-label="Permalink to &quot;分布式事务解决方案 ★★★&quot;">​</a></h2><h3 id="为什么需要" tabindex="-1">为什么需要 <a class="header-anchor" href="#为什么需要" aria-label="Permalink to &quot;为什么需要&quot;">​</a></h3><ul><li>单机事务靠数据库本地事务，微服务下跨服务/跨库需分布式事务。</li></ul><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ol><li>2PC（两阶段提交）：准备阶段 + 提交阶段；强一致但同步阻塞、协调者单点、性能差。</li><li>TCC（Try-Confirm-Cancel）：业务层三段，Try 预留资源、Confirm 确认、Cancel 取消；灵活但侵入业务、实现复杂。</li><li>SAGA：长事务拆成多个本地事务 + 补偿，适合长流程、高并发；最终一致。</li><li>本地消息表：本地事务 + 消息表，通过消息驱动后续服务，靠定时任务/重试保证最终一致。</li><li>事务消息（RocketMQ 半消息）：先发半消息，本地事务成功后提交，否则回滚。</li><li>最大努力通知：尽力通知，配合对账/人工兜底。</li></ol><h3 id="中间件" tabindex="-1">中间件 <a class="header-anchor" href="#中间件" aria-label="Permalink to &quot;中间件&quot;">​</a></h3><ul><li>Seata：AT（自动，无侵入，基于 undo log + 全局锁）、TCC、SAGA、XA 模式。</li></ul><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「2PC 有什么问题？」→ 同步阻塞、协调者单点故障、数据不一致风险。</li><li>「Seata AT 模式原理？」→ 全局事务协调 + 各服务本地事务 + undo log 回滚 + 全局锁防脏写。</li></ul><hr><h2 id="分布式-id-生成-★★★" tabindex="-1">分布式 ID 生成 ★★★ <a class="header-anchor" href="#分布式-id-生成-★★★" aria-label="Permalink to &quot;分布式 ID 生成 ★★★&quot;">​</a></h2><h3 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to &quot;方案对比&quot;">​</a></h3><ul><li>UUID：本地生成、简单，但无序（不适合做数据库主键，导致页分裂）、过长。</li><li>数据库自增：简单但单点、性能瓶颈，不适合分布式。</li><li>号段模式（如 Leaf）：从数据库批量取一段 id 缓存，减少访问。</li><li>雪花算法（Snowflake）：时间戳 + 机器 id + 序列号，趋势递增、高性能，主流。</li></ul><h3 id="雪花算法" tabindex="-1">雪花算法 <a class="header-anchor" href="#雪花算法" aria-label="Permalink to &quot;雪花算法&quot;">​</a></h3><ul><li>结构：1 位符号 + 41 位时间戳 + 10 位机器 id + 12 位序列号。</li><li>优点：本地生成、趋势递增、高性能；缺点：依赖时钟，时钟回拨会导致重复 id（需处理）。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「时钟回拨怎么处理？」→ 等待时钟追上、抛异常、用备用机器 id、记录上次时间戳。</li></ul><hr><h2 id="限流算法-令牌桶、漏桶、滑动窗口-★★★" tabindex="-1">限流算法：令牌桶、漏桶、滑动窗口 ★★★ <a class="header-anchor" href="#限流算法-令牌桶、漏桶、滑动窗口-★★★" aria-label="Permalink to &quot;限流算法：令牌桶、漏桶、滑动窗口 ★★★&quot;">​</a></h2><h3 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h3><ul><li>固定窗口计数器：一段时间内限固定次数；边界问题（窗口临界突发）。</li><li>滑动窗口：细分窗口平滑，解决固定窗口边界问题。</li><li>漏桶：固定速率流出，能限制平均速率，但无法应对突发（超出即丢弃）。</li><li>令牌桶：固定速率放令牌，桶满停止；能允许一定突发（有令牌即可）。</li></ul><h3 id="选择" tabindex="-1">选择 <a class="header-anchor" href="#选择" aria-label="Permalink to &quot;选择&quot;">​</a></h3><ul><li>令牌桶允许突发，适合大多数 API 限流；漏桶严格平滑，适合需要恒定速率的场景。</li></ul><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li>Sentinel、Guava RateLimiter（令牌桶）、Redis + Lua 脚本、网关限流。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「令牌桶和漏桶区别？」→ 令牌桶允许突发流量，漏桶严格匀速。</li></ul><hr><h2 id="熔断、降级、隔离-★★★" tabindex="-1">熔断、降级、隔离 ★★★ <a class="header-anchor" href="#熔断、降级、隔离-★★★" aria-label="Permalink to &quot;熔断、降级、隔离 ★★★&quot;">​</a></h2><ul><li>熔断：依赖服务异常比例超阈值时，直接返回兜底，快速失败，防止级联故障（断路器：关闭→打开→半开）。</li><li>降级：系统压力大时，关闭非核心功能，保核心链路。</li><li>隔离：线程池/信号量隔离，防止某个依赖占满资源拖垮整体（Hystrix 线程池隔离）。</li></ul><h3 id="工具-1" tabindex="-1">工具 <a class="header-anchor" href="#工具-1" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li>Sentinel、Resilience4j、Hystrix（已停维护）。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「熔断和降级区别？」→ 熔断是「被动应对依赖故障」，降级是「主动关功能保核心」。</li></ul><hr><h2 id="接口幂等性-★★★" tabindex="-1">接口幂等性 ★★★ <a class="header-anchor" href="#接口幂等性-★★★" aria-label="Permalink to &quot;接口幂等性 ★★★&quot;">​</a></h2><h3 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h3><ul><li>网络重试、用户重复点击、消息重复投递导致重复请求，需保证重复执行结果一致。</li></ul><h3 id="方案-1" tabindex="-1">方案 <a class="header-anchor" href="#方案-1" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ul><li>唯一索引：数据库唯一约束，重复插入失败。</li><li>Token 机制：提交前先获取 token，提交时校验并删除 token（防重复提交）。</li><li>状态机：只有特定状态能流转（如待支付→已支付）。</li><li>乐观锁：版本号/条件更新。</li><li>Redis 分布式锁 / setnx。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「哪些操作天然幂等？」→ 查询、删除（按 id）、更新（绝对值）；非幂等如「余额 += 100」。</li></ul><hr><h2 id="一致性哈希-★★★" tabindex="-1">一致性哈希 ★★★ <a class="header-anchor" href="#一致性哈希-★★★" aria-label="Permalink to &quot;一致性哈希 ★★★&quot;">​</a></h2><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><ul><li>把节点和 key 都哈希到同一个环上，key 顺时针找到的第一个节点就是它归属的节点。</li><li>节点增删时，只影响相邻的一小段数据，最小化迁移。</li></ul><h3 id="虚拟节点" tabindex="-1">虚拟节点 <a class="header-anchor" href="#虚拟节点" aria-label="Permalink to &quot;虚拟节点&quot;">​</a></h3><ul><li>每个真实节点映射多个虚拟节点，解决数据倾斜和分布不均。</li></ul><h3 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h3><ul><li>分布式缓存分片（如 Memcached 客户端）、负载均衡、数据分片。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「一致性哈希 vs 普通哈希取模？」→ 取模在节点数变化时几乎所有 key 都要重新映射；一致性哈希只迁移少部分。</li></ul><hr><h2 id="高并发场景-秒杀系统设计-★★★" tabindex="-1">高并发场景：秒杀系统设计 ★★★ <a class="header-anchor" href="#高并发场景-秒杀系统设计-★★★" aria-label="Permalink to &quot;高并发场景：秒杀系统设计 ★★★&quot;">​</a></h2><h3 id="核心问题与方案" tabindex="-1">核心问题与方案 <a class="header-anchor" href="#核心问题与方案" aria-label="Permalink to &quot;核心问题与方案&quot;">​</a></h3><ol><li>高并发读/写 → 前端限流、CDN 缓存、Nginx 限流、Redis 预扣库存。</li><li>超卖 → Redis 原子扣减（decr/lua）、数据库乐观锁（<code>update ... where stock &gt; 0</code>）。</li><li>流量洪峰 → 消息队列削峰、令牌桶限流。</li><li>数据库压力 → 读写分离、分库分表。</li><li>防黄牛 → 验证码、限购（一人一单）、风控。</li><li>数据一致性 → 库存扣减 + 订单 + 异步消息 + 补偿。</li></ol><h3 id="完整链路" tabindex="-1">完整链路 <a class="header-anchor" href="#完整链路" aria-label="Permalink to &quot;完整链路&quot;">​</a></h3><ul><li>用户点击 → CDN/静态页 → 网关限流 → 秒杀接口 → Redis 预扣库存（原子）→ 消息队列 → 生成订单 → 数据库落库 → 异步扣真实库存。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么防超卖？」→ Redis 原子扣减 + 数据库乐观锁/唯一索引兜底。</li><li>「热点商品怎么处理？」→ 本地缓存 + Redis 集群 + 分桶/多副本分流。</li></ul><hr><h2 id="分布式锁的实现与问题-★★★" tabindex="-1">分布式锁的实现与问题 ★★★ <a class="header-anchor" href="#分布式锁的实现与问题-★★★" aria-label="Permalink to &quot;分布式锁的实现与问题 ★★★&quot;">​</a></h2><ul><li>见中间件 Redis 部分：SET NX EX + Lua 释放 + 看门狗续期。</li><li>其他：ZooKeeper 临时顺序节点（watch 机制，羊群效应）、数据库唯一索引。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Redis 和 ZK 分布式锁区别？」→ Redis 基于过期时间 + 续期，性能高但主从切换可能丢锁；ZK 基于临时节点，强一致但性能较低。</li></ul><hr><h2 id="服务治理-注册发现、配置中心、网关-★★★" tabindex="-1">服务治理：注册发现、配置中心、网关 ★★★ <a class="header-anchor" href="#服务治理-注册发现、配置中心、网关-★★★" aria-label="Permalink to &quot;服务治理：注册发现、配置中心、网关 ★★★&quot;">​</a></h2><ul><li>注册发现：服务启动注册到注册中心（Nacos/Eureka），调用方从注册中心拉取实例列表，配合负载均衡。</li><li>配置中心：集中管理配置，动态刷新（Nacos Config）。</li><li>网关：统一入口、路由、鉴权、限流、灰度。</li></ul><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「服务发现怎么实现？」→ 服务注册 + 心跳续约 + 拉取服务列表 + 负载均衡调用。</li></ul><hr><h2 id="分布式链路追踪-★★☆" tabindex="-1">分布式链路追踪 ★★☆ <a class="header-anchor" href="#分布式链路追踪-★★☆" aria-label="Permalink to &quot;分布式链路追踪 ★★☆&quot;">​</a></h2><ul><li>目的：定位跨服务调用链、性能瓶颈、故障。</li><li>方案：SkyWalking、Zipkin、Jaeger。</li><li>核心：traceId 贯穿整条链路，span 表示一次调用。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「traceId 怎么传递？」→ 通过请求头（如 X-Trace-Id）透传，各服务日志记录。</li></ul><hr><h2 id="高并发下的数据一致性-缓存双写、读写分离-★★☆" tabindex="-1">高并发下的数据一致性：缓存双写、读写分离 ★★☆ <a class="header-anchor" href="#高并发下的数据一致性-缓存双写、读写分离-★★☆" aria-label="Permalink to &quot;高并发下的数据一致性：缓存双写、读写分离 ★★☆&quot;">​</a></h2><ul><li>缓存双写一致性：见中间件篇（Cache Aside + 延迟双删 + binlog 订阅）。</li><li>读写分离：主写从读，注意主从延迟（实时性要求高的读走主库）。</li></ul><hr><h2 id="幂等-分布式锁-限流在订单场景的综合运用-★★☆" tabindex="-1">幂等 + 分布式锁 + 限流在订单场景的综合运用 ★★☆ <a class="header-anchor" href="#幂等-分布式锁-限流在订单场景的综合运用-★★☆" aria-label="Permalink to &quot;幂等 + 分布式锁 + 限流在订单场景的综合运用 ★★☆&quot;">​</a></h2><ul><li>下单流程：限流（防刷）→ 幂等（防重复提交）→ 分布式锁（防并发扣减）→ 库存扣减（乐观锁）→ 生成订单 → 消息通知。</li><li>体现：多个手段叠加保证高并发下的正确性与可用性。</li></ul>',92)]))}const q=l(t,[["render",h]]);export{b as __pageData,q as default};
